<script setup lang="ts">
import {computed,ref,markRaw} from 'vue';
import type {AdminMediaAsset,Purpose} from '../../../../shared/contracts';
import {EditorModel,normalizeMedia,purposeLabels,safeMediaUrl,errorMessage} from '../api';
const props=defineProps<{model:EditorModel}>();
const purpose=ref<Purpose>(props.model.kind==='diary'?'diaryPage':props.model.kind==='video'?'video':props.model.kind==='resource'?'resourceFile':'cover');
const jobs=ref<{file:File;purpose:Purpose;key:string;state:'waiting'|'uploading'|'failed'|'done';progress:number}[]>([]);
const allowed=computed<Purpose[]>(()=>props.model.kind==='diary'?['diaryPage','cover']:props.model.kind==='video'?['video','cover']:props.model.kind==='resource'?['resourceFile','cover']:['cover']);
const accept=computed(()=>purpose.value==='video'?'.mp4':purpose.value==='resourceFile'?'.zip,.pdf,.txt,.md':'.jpg,.jpeg,.png,.webp');
const unlinked=computed(()=>props.model.assets.filter(a=>!props.model.form.media.some(m=>m.assetId===a.assetId)));
function asset(id:string){return props.model.assets.find(a=>a.assetId===id);}
function thumb(id:string){return safeMediaUrl(asset(id)?.variants.find(v=>v.name==='thumbnail')?.url);}
function select(event:Event){const input=event.target as HTMLInputElement;for(const file of Array.from(input.files||[])){jobs.value.push({file:markRaw(file),purpose:purpose.value,key:crypto.randomUUID(),state:'waiting',progress:0});}input.value='';}
async function send(index:number){const job=jobs.value[index],m=props.model;if(!m.saved||m.locked)return;const max=job.purpose==='video'?300:job.purpose==='resourceFile'?50:20;if(job.file.size>max*1024*1024){job.state='failed';m.error=`文件超过 ${max} MiB 限制，请移除后选择其他文件`;return;}await m.attempt('上传文件',async()=>{job.state='uploading';try{const result=await m.api.upload(m.saved!.id,job.purpose,job.file,job.key,p=>job.progress=p);m.keepAsset(result.asset);job.state='done';try{m.link(result.asset);}catch(e){m.notice=errorMessage(e);}if(job.purpose==='resourceFile'&&m.form.resource?.mode!=='download')m.notice='已归档，未关联；改为本站下载后可选择此文件';}catch(e){job.state='failed';throw e;}});}
async function sendAll(){for(let i=0;i<jobs.value.length;i++){if(jobs.value[i].state==='waiting'){await send(i);if(jobs.value[i].state!=='done')break;}}}
async function recover(){const m=props.model;m.busy=true;m.error='';try{await m.refreshAssets();m.notice='已读取归档文件；加入编辑区后仍需保存关联';}catch(e){m.error=errorMessage(e);}finally{m.busy=false;}}
function link(a:AdminMediaAsset){try{props.model.link(a);}catch(e){props.model.error=errorMessage(e);}}
function move(index:number,delta:number){const media=[...props.model.form.media];let target=index+delta;while(target>=0&&target<media.length&&media[target].role!==media[index].role)target+=delta;if(target<0||target>=media.length)return;[media[index],media[target]]=[media[target],media[index]];props.model.form.media=normalizeMedia(media);props.model.notice='顺序已修改，尚未保存';}
function remove(index:number){props.model.form.media=normalizeMedia(props.model.form.media.filter((_,i)=>i!==index));props.model.notice='已移除编辑区关联，保存后生效；归档原件保留';}
</script>
<template><section class="media"><h2>文件与页序</h2><p class="notice">上传 → 调整顺序与说明 → 保存关联。上传成功不会自动发布；移除关联不会删除原件。</p><template v-if="model.saved"><fieldset :disabled="model.locked"><div class="upload"><label>文件用途<select v-model="purpose"><option v-for="p in allowed" :key="p" :value="p">{{purposeLabels[p]}}</option></select></label><label>选择文件<input type="file" :accept="accept" multiple @change="select"></label></div><p class="muted">图片 ≤20 MiB；MP4 ≤300 MiB；ZIP/PDF/TXT/MD ≤50 MiB。实际格式由服务端检查。</p><button type="button" :disabled="!jobs.some(j=>j.state==='waiting')" @click="sendAll">上传所选文件</button><ul><li v-for="(job,index) in jobs" :key="job.key"><span>{{job.file.name}} · {{purposeLabels[job.purpose]}} · {{job.state==='done'?'已上传':job.state==='failed'?'上传失败':job.state==='waiting'?'等待上传':job.progress===100?'正在验证文件…':`上传 ${job.progress}%`}}</span><button v-if="job.state==='failed'" type="button" @click="send(index)">重试此文件</button><button v-if="job.state!=='uploading'" type="button" class="quiet" @click="jobs.splice(index,1)">移出队列</button></li></ul><h3>本次保存的媒体</h3><p v-if="!model.form.media.length" class="muted">尚未关联文件。</p><ol><li v-for="(link,index) in model.form.media" :key="link.assetId" class="linked"><img v-if="thumb(link.assetId)" :src="thumb(link.assetId)" alt="文件缩略图"><div><strong>{{purposeLabels[link.role]}} {{link.position+1}}</strong><p>{{asset(link.assetId)?.originalName||'已关联文件'}}</p><label>图片或附件说明<input v-model="link.alt" maxlength="300"></label><div class="buttons"><button type="button" class="quiet" :aria-label="`上移第 ${link.position+1} 个${purposeLabels[link.role]}`" @click="move(index,-1)">上移</button><button type="button" class="quiet" :aria-label="`下移第 ${link.position+1} 个${purposeLabels[link.role]}`" @click="move(index,1)">下移</button><button type="button" class="quiet" @click="remove(index)">移除关联</button></div></div></li></ol></fieldset><button type="button" :disabled="model.busy||!!model.pending" @click="recover">找回已上传的归档文件</button><ul v-if="unlinked.length"><li v-for="a in unlinked" :key="a.assetId"><span>{{a.originalName}} · {{purposeLabels[a.purpose]}}</span><button type="button" :disabled="model.locked||(a.purpose==='resourceFile'&&model.form.resource?.mode!=='download')" @click="link(a)">加入编辑区</button><a v-if="safeMediaUrl(a.variants.find(v=>v.name==='original')?.url)" :href="safeMediaUrl(a.variants.find(v=>v.name==='original')?.url)">下载归档原件</a></li></ul></template><p v-else>先保存私密草稿，再上传文件。</p></section></template>
<style scoped>input,select{width:100%;min-width:0}.media{margin:28px 0}fieldset{border:0;padding:0;min-width:0}.upload,.buttons{display:flex;flex-wrap:wrap;gap:12px}label{display:grid;gap:6px;min-width:0}.upload label{flex:1;min-width:140px}ul,ol{padding:0;list-style:none}li{display:flex;flex-wrap:wrap;align-items:center;gap:12px;border-bottom:1px solid var(--line);padding:14px 0;overflow-wrap:anywhere}li span{flex:1;min-width:100px}.linked{align-items:start}.linked>div{flex:1;min-width:150px}img{width:96px;height:128px;object-fit:contain;background:var(--bg)}p{margin:8px 0}h3{font-size:16px}a{color:var(--accent)}</style>
